def perform_operation(num1, num2, operator):
    """Perform the specified operation on two numbers and return the result."""
    if operator == '+':
        return num1 + num2
    elif operator == '-':
        return num1 - num2
    elif operator == '*':
        return num1 * num2
    elif operator == '/':
        return num1 / num2
    else:
        raise ValueError(f"Invalid operator '{operator}'. Please use '+' for addition, '-' for subtraction, '*' for multiplication, or '/' for division.")

